insert into public.categories(id,slug,name) values ('853cd46b-0f58-507d-b055-cd6dc9fd9911','vishing','{"en": "Vishing", "ar": "التصيّد الصوتي"}'::jsonb) on conflict (id) do update set name=excluded.name;
