insert into public.categories(id,slug,name) values ('c9076d9b-d5b5-5a7c-9ec8-4e091216d7e5','sniffing','{"en": "Network sniffing", "ar": "التنصّت على الشبكة"}'::jsonb) on conflict (id) do update set name=excluded.name;
insert into public.categories(id,slug,name) values ('92c195f4-e8f0-5e6e-91f8-80f35a544987','mitm','{"en": "Man-in-the-middle", "ar": "هجوم الوسيط"}'::jsonb) on conflict (id) do update set name=excluded.name;
