insert into public.categories(id,slug,name) values ('c4ac4a59-8f2a-55bd-8559-bfe95acb537f','usb','{"en": "USB baiting", "ar": "الطُّعم عبر USB"}'::jsonb) on conflict (id) do update set name=excluded.name;
insert into public.categories(id,slug,name) values ('b4b08b5d-6a7f-5b42-8c42-0c57f8f3f749','quishing','{"en": "QR-code phishing", "ar": "التصيّد عبر رموز QR"}'::jsonb) on conflict (id) do update set name=excluded.name;
insert into public.categories(id,slug,name) values ('f45189f5-84a2-538b-968b-75c2d58f37b7','spear','{"en": "Spear phishing and spoofing", "ar": "التصيّد الموجّه وانتحال النطاق"}'::jsonb) on conflict (id) do update set name=excluded.name;
insert into public.categories(id,slug,name) values ('473acc42-0da0-54ed-824e-4d7d2ac319bc','ransomware','{"en": "Ransomware", "ar": "برمجيات الفدية"}'::jsonb) on conflict (id) do update set name=excluded.name;
insert into public.categories(id,slug,name) values ('5d5cb559-db54-5ac7-9b78-c60038d7eb06','session','{"en": "Session hijacking", "ar": "اختطاف الجلسات"}'::jsonb) on conflict (id) do update set name=excluded.name;
insert into public.categories(id,slug,name) values ('27e717a1-ea9a-56f9-8446-a99cb07f9a49','incident','{"en": "Incident reporting", "ar": "الإبلاغ عن الحوادث"}'::jsonb) on conflict (id) do update set name=excluded.name;
insert into public.questions(id,position,stage,category_id,scenario) values ('61873a84-f98e-5e03-afd7-2a6146a44b47',1,1,'5e3bd001-fa07-5578-8b88-06158ebdd8df','{"en": "Lina, a university student, gets an email that looks like it comes from the IT department. It says her account will be suspended in two hours unless she confirms her credentials, and it links to a login page that looks identical to the university portal.", "ar": "تتلقى لينا، وهي طالبة جامعية، بريدًا إلكترونيًا يبدو أنه من قسم تقنية المعلومات. تقول الرسالة إن حسابها سيُعلَّق خلال ساعتين ما لم تؤكد بيانات دخولها، وتتضمن رابطًا إلى صفحة تسجيل دخول تطابق بوابة الجامعة تمامًا."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('f21b6423-80ac-557a-85cf-a564cfe9cb3c','61873a84-f98e-5e03-afd7-2a6146a44b47',0,'{"en": "Open the link and inspect the login page carefully before typing anything.", "ar": "تفتح الرابط وتفحص صفحة الدخول جيدًا قبل كتابة أي شيء."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('52c7dfc6-78c5-568d-9eeb-dec344fd8a7d','61873a84-f98e-5e03-afd7-2a6146a44b47',1,'{"en": "Go to the portal by typing its address yourself and look for notices.", "ar": "تدخل إلى البوابة بكتابة عنوانها بنفسها وتبحث عن إشعارات."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('61ae75c4-b806-5ca3-8232-9a83c334c70f','61873a84-f98e-5e03-afd7-2a6146a44b47',2,'{"en": "Reply to the email and ask the sender to confirm the request is genuine.", "ar": "تردّ على الرسالة وتطلب من المرسل تأكيد صحة الطلب."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('bf53607a-a132-593d-b2cf-7c460cab2da7','61873a84-f98e-5e03-afd7-2a6146a44b47',3,'{"en": "Forward the email to a classmate to see whether she received it too.", "ar": "تحوّل الرسالة إلى زميلة لتعرف إن كانت وصلتها أيضًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('61873a84-f98e-5e03-afd7-2a6146a44b47','52c7dfc6-78c5-568d-9eeb-dec344fd8a7d','{"en": {"threat": "Phishing", "lesson": "Phishing combines urgency with a convincing copy of a trusted site. Leaving the message and reaching the service through an address you type or a saved bookmark is safe, because nothing in the email can steer you.", "wrong": ["Merely loading a fake page can expose you to harmful scripts, and a perfect look proves nothing. The risk is judging the page instead of leaving it.", "", "Your reply goes to the attacker, who will happily confirm. Never verify a message through the same channel it arrived on.", "Forwarding spreads the lure, and a classmate saying ''me too'' proves nothing; you may both be targeted."]}, "ar": {"threat": "التصيّد الاحتيالي (Phishing)", "lesson": "يجمع التصيّد بين الاستعجال ونسخة مقنعة من موقع موثوق. ترك الرسالة والوصول إلى الخدمة عبر عنوان تكتبه بنفسك أو إشارة مرجعية محفوظة هو الأسلم، لأن شيئًا في البريد لا يستطيع توجيهك.", "wrong": ["مجرد فتح صفحة مزيّفة قد يعرّضك لبرمجيات ضارة، ومظهرها المطابق لا يثبت شيئًا. الخطأ هو الحكم على الصفحة بدل مغادرتها.", "", "ردّك يصل إلى المحتال وسيؤكد لك الطلب بكل سرور. لا تتحقق من رسالة عبر القناة نفسها التي وصلت منها.", "التحويل ينشر الطُّعم، وقول زميلتك «وصلتني أيضًا» لا يثبت شيئًا؛ فقد تكونان مستهدفتين معًا."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('8cbd0043-2ef3-559b-ac94-de63b2fd2c68',2,1,'4766252b-0dc6-56a7-8f2f-a3057605d335','{"en": "Omar gets an SMS: ''Your parcel is held at the depot. Pay a small customs fee to release it,'' followed by a short link. He is waiting for an online order, but the message names neither the store nor the item.", "ar": "يتلقى عمر رسالة نصية: «طردك محتجز في المستودع. ادفع رسوم جمركية بسيطة للإفراج عنه»، يليها رابط قصير. هو ينتظر فعلًا طلبًا من متجر إلكتروني، لكن الرسالة لا تذكر اسم المتجر ولا المنتج."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('65f97cd4-d289-5133-a56e-513fea36bf21','8cbd0043-2ef3-559b-ac94-de63b2fd2c68',0,'{"en": "Pay the small fee quickly, since the delivery is expected anyway.", "ar": "يدفع الرسوم البسيطة بسرعة، فالتوصيل متوقع على أي حال."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('abbb4a7f-aec6-5a43-8e38-e42efe0f6547','8cbd0043-2ef3-559b-ac94-de63b2fd2c68',1,'{"en": "Reply STOP so the sender removes his number from their list.", "ar": "يردّ بكلمة STOP كي يحذف المرسل رقمه من قائمته."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('7aeff024-8457-5e31-a71c-c8d092489bcc','8cbd0043-2ef3-559b-ac94-de63b2fd2c68',2,'{"en": "Open the link in a private browser window so nothing is saved.", "ar": "يفتح الرابط في نافذة تصفح خاص حتى لا يُحفظ شيء."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('ff207837-092a-5c25-bc3e-13587793beb7','8cbd0043-2ef3-559b-ac94-de63b2fd2c68',3,'{"en": "Check the order in the store''s or courier''s official app.", "ar": "يتحقق من الطلب في تطبيق المتجر أو شركة الشحن الرسمي."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('8cbd0043-2ef3-559b-ac94-de63b2fd2c68','ff207837-092a-5c25-bc3e-13587793beb7','{"en": {"threat": "Smishing (SMS phishing)", "lesson": "Smishing uses delivery fees, fines and prize alerts because people act fast on texts. Even when you expect a parcel, a message that names no store or item is generic. Check the order in an app or site you already trust.", "wrong": ["A small fee is the hook; the real goal is your card details, which can be reused later.", "Replying confirms your number is active and read, which usually brings more messages.", "A private window does not stop a fake page from collecting what you type.", ""]}, "ar": {"threat": "التصيّد عبر الرسائل النصية (Smishing)", "lesson": "يعتمد هذا الهجوم على رسوم التوصيل والمخالفات وإشعارات الجوائز لأن الناس يتصرفون بسرعة مع الرسائل النصية. حتى لو كنت تنتظر طردًا، فالرسالة التي لا تذكر متجرًا أو منتجًا رسالة عامة. تحقق من الطلب عبر تطبيق أو موقع تثق به مسبقًا.", "wrong": ["الرسوم الصغيرة هي الطُّعم؛ الهدف الحقيقي بيانات بطاقتك التي يمكن إعادة استخدامها لاحقًا.", "الردّ يؤكد أن رقمك فعّال ويُقرأ، وغالبًا ما يجلب المزيد من الرسائل.", "التصفح الخاص لا يمنع صفحة مزيّفة من جمع ما تكتبه.", ""]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('e0c9f1c4-1542-593b-b972-6fe64049560f',3,1,'853cd46b-0f58-507d-b055-cd6dc9fd9911','{"en": "A caller says she works in your bank''s fraud department. She knows your name and the last four digits of your card, says a suspicious payment is in progress, and asks you to read out the six-digit code you are about to receive by SMS so she can block it.", "ar": "تتصل بك امرأة تقول إنها من قسم مكافحة الاحتيال في مصرفك. تعرف اسمك وآخر أربعة أرقام من بطاقتك، وتقول إن عملية دفع مشبوهة جارية، وتطلب منك قراءة الرمز المكوّن من ستة أرقام الذي سيصلك برسالة نصية لتوقفها."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('747c32a3-9054-5033-bdb9-83ab12cbd34e','e0c9f1c4-1542-593b-b972-6fe64049560f',0,'{"en": "Hang up, then call the number on your bank card to ask about the alert.", "ar": "تنهي المكالمة ثم تتصل بالرقم المطبوع على بطاقتك لتسأل عن التنبيه."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('a4fdf2d2-f730-55ca-a33d-7e0dcabb2666','e0c9f1c4-1542-593b-b972-6fe64049560f',1,'{"en": "Read her the code, since she already knows details only the bank would have.", "ar": "تقرأ لها الرمز، فهي تعرف تفاصيل لا يعرفها إلا المصرف."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('8c4faab3-1fc5-59ba-ae47-427aa78be858','e0c9f1c4-1542-593b-b972-6fe64049560f',2,'{"en": "Ask her to prove her identity by telling you your full account balance.", "ar": "تطلب منها إثبات هويتها بذكر رصيد حسابك كاملًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('937e202e-d2cc-5642-b43c-123ac0d4d5be','e0c9f1c4-1542-593b-b972-6fe64049560f',3,'{"en": "Tell her you will read the code only after she emails you an official notice.", "ar": "تخبرها أنك لن تقرأ الرمز إلا بعد أن ترسل لك إشعارًا رسميًا بالبريد."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('e0c9f1c4-1542-593b-b972-6fe64049560f','747c32a3-9054-5033-bdb9-83ab12cbd34e','{"en": {"threat": "Vishing (voice phishing)", "lesson": "Vishing callers build trust with a few real details and create panic. A one-time code approves an action, and a real bank never asks you to read it out. Ending the call and dialling the number on your card puts you back in control.", "wrong": ["", "Those details are easy to buy or collect from earlier leaks. The code lets the attacker approve their own action.", "Scammers can often see some account details, and staying on the call keeps you under their control.", "Emails can be forged, and you would remain on a call she is steering. End it and use a number you trust."]}, "ar": {"threat": "التصيّد الصوتي (Vishing)", "lesson": "يبني المحتالون الثقة بتفاصيل حقيقية قليلة ثم يصنعون الذعر. الرمز لمرة واحدة يوافق على عملية ما، والمصرف الحقيقي لا يطلب منك قراءته. إنهاء المكالمة والاتصال بالرقم المطبوع على بطاقتك يعيد إليك زمام الأمور.", "wrong": ["", "هذه التفاصيل يسهل شراؤها أو جمعها من تسريبات سابقة. والرمز يمنح المهاجم موافقة على عمليته.", "قد يرى المحتالون بعض بيانات الحساب، وبقاؤك على الخط يبقيك تحت سيطرتهم.", "البريد يمكن تزويره، وستبقى على مكالمة تقودها هي. أنهِها واستخدم رقمًا تثق به."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('eb6ed992-60ac-5b7f-a719-160ce160f031',4,1,'7a303304-d8f0-571c-86cb-0fa3fba995ac','{"en": "Sara works in accounts. An email from a supplier she has dealt with before has an attachment named Invoice_2291.docm and the line ''See attached, payment overdue.'' The supplier normally sends PDF invoices, the message arrived at 3 a.m., and the file asks her to ''Enable content'' to view it.", "ar": "تعمل سارة في قسم الحسابات. وصلها بريد من مورّد تعاملت معه سابقًا يحمل مرفقًا باسم Invoice_2291.docm وعبارة «مرفق الفاتورة، السداد متأخر». المورّد يرسل فواتيره عادةً بصيغة PDF، ووصلت الرسالة في الثالثة فجرًا، والملف يطلب منها «تمكين المحتوى» لعرضه."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('125673c0-bf50-5301-b732-0e4875a229de','eb6ed992-60ac-5b7f-a719-160ce160f031',0,'{"en": "Open it in Protected View and read it without enabling anything.", "ar": "تفتحه في وضع العرض المحمي وتقرأه دون تمكين أي شيء."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('724398d6-2699-593a-ad27-9cbf641344fb','eb6ed992-60ac-5b7f-a719-160ce160f031',1,'{"en": "Save it to the desktop and scan it with antivirus before opening it.", "ar": "تحفظه على سطح المكتب وتفحصه بمضاد الفيروسات قبل فتحه."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('fe1b26ed-cc7a-597f-8df9-e8f1ca50e4b8','eb6ed992-60ac-5b7f-a719-160ce160f031',2,'{"en": "Phone the supplier on a known number to ask whether they sent it.", "ar": "تتصل بالمورّد على رقم معروف وتسأله إن كان قد أرسله."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('322f9a6c-04ed-5f85-a38a-a7a08ce064f5','eb6ed992-60ac-5b7f-a719-160ce160f031',3,'{"en": "Open it, and enable content only if the invoice amount looks familiar.", "ar": "تفتحه وتمكّن المحتوى فقط إذا بدا المبلغ مألوفًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('eb6ed992-60ac-5b7f-a719-160ce160f031','fe1b26ed-cc7a-597f-8df9-e8f1ca50e4b8','{"en": {"threat": "Malicious attachment", "lesson": "Attackers hijack or imitate real suppliers, and ''Enable content'' on an office file can launch hidden macros. A short call to a known number settles whether the invoice is real before any file is opened.", "wrong": ["Protected View reduces risk, but it is not a guarantee, and the document is built to push you to enable content. Verify first.", "A scan only catches known threats; new malware often passes. The real question is whether the sender is genuine.", "", "An amount can be copied from a genuine invoice. Enabling content is exactly what runs the hidden macro."]}, "ar": {"threat": "مرفق خبيث (Malicious attachment)", "lesson": "يخترق المهاجمون حسابات موردين حقيقيين أو ينتحلونها، وزر «تمكين المحتوى» في ملف مكتبي قد يشغّل ماكرو خفيًا. مكالمة قصيرة إلى رقم معروف تحسم صحة الفاتورة قبل فتح أي ملف.", "wrong": ["العرض المحمي يقلل الخطر لكنه لا يضمنه، والملف مصمم لدفعك إلى تمكين المحتوى. تحقق أولًا.", "الفحص يكشف التهديدات المعروفة فقط؛ كثير من البرمجيات الجديدة يمر. والسؤال الحقيقي: هل المرسل أصلي؟", "", "يمكن نسخ المبلغ من فاتورة حقيقية. وتمكين المحتوى هو بالضبط ما يشغّل الماكرو الخفي."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('b65c38b4-3d25-5f47-a33c-a409d43bedf2',5,1,'a0d7f21f-54fb-5070-976d-5231dc093c1e','{"en": "While reading a recipe blog, Yusuf''s browser shows a full-page pop-up: ''Your browser is out of date and infected. Install the security update now.'' A button downloads a file named BrowserUpdate.exe.", "ar": "أثناء قراءة مدوّنة وصفات، تظهر على متصفح يوسف نافذة منبثقة بملء الشاشة: «متصفحك قديم ومصاب. ثبّت التحديث الأمني الآن». ويحمّل زر فيها ملفًا باسم BrowserUpdate.exe."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('c222df6d-5f63-5ebc-abea-ecf226b3abce','b65c38b4-3d25-5f47-a33c-a409d43bedf2',0,'{"en": "Install it, then run a scan afterwards in case something slipped through.", "ar": "يثبّته ثم يجري فحصًا لاحقًا تحسبًا لتسلل شيء ما."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('074041a3-934e-5038-a9ac-345d58056182','b65c38b4-3d25-5f47-a33c-a409d43bedf2',1,'{"en": "Close the tab, then update the browser from its own settings menu.", "ar": "يغلق التبويب ثم يحدّث المتصفح من قائمة إعداداته."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('35ffa3e2-fdcc-5a96-99c6-ea88ee81bbf5','b65c38b4-3d25-5f47-a33c-a409d43bedf2',2,'{"en": "Click the pop-up''s X to dismiss it, then keep browsing the blog.", "ar": "ينقر على علامة X في النافذة لإغلاقها ثم يواصل تصفح المدونة."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('2b142ef4-74aa-5224-9100-52d08cfd5f39','b65c38b4-3d25-5f47-a33c-a409d43bedf2',3,'{"en": "Download the file but read reviews of the website before running it.", "ar": "ينزّل الملف لكنه يقرأ تقييمات الموقع قبل تشغيله."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('b65c38b4-3d25-5f47-a33c-a409d43bedf2','074041a3-934e-5038-a9ac-345d58056182','{"en": {"threat": "Drive-by download / fake update", "lesson": "Fake update pop-ups imitate security warnings so that you run the malware yourself. Real browsers update through their own settings or automatically, never through a pop-up on a website.", "wrong": ["Running the file is the infection. Scanning afterwards may come too late.", "", "The X can be fake, and staying on a page that serves such pop-ups keeps you exposed to automatic downloads.", "Reviews of a blog do not make a pop-up file trustworthy. Real updates never arrive this way."]}, "ar": {"threat": "التنزيل الخفي / التحديث المزيف", "lesson": "تقلّد هذه النوافذ تحذيرات الأمان كي تشغّل البرمجية الخبيثة بنفسك. المتصفحات الحقيقية تتحدث من إعداداتها أو تلقائيًا، وليس عبر نافذة منبثقة في موقع.", "wrong": ["تشغيل الملف هو العدوى نفسها. والفحص بعد ذلك قد يأتي متأخرًا.", "", "علامة X قد تكون مزيّفة، والبقاء في صفحة تعرض مثل هذه النوافذ يبقيك عرضة لتنزيلات تلقائية.", "تقييمات المدونة لا تجعل ملف النافذة موثوقًا. التحديثات الحقيقية لا تصل بهذه الطريقة."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('7858588f-a162-5abc-9ed2-0457e00d7ef0',6,2,'23630b07-64a9-565a-919d-cb7b6c083a94','{"en": "Noor receives a notice that a forum she used years ago was breached. She uses the same password, with a small change at the end, for her email, her shopping account and her banking app.", "ar": "تصل نور رسالة تفيد بتسريب بيانات منتدى استخدمته قبل سنوات. وهي تستعمل كلمة المرور نفسها، مع تعديل بسيط في آخرها، لبريدها الإلكتروني وحساب التسوق وتطبيق مصرفها."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('e3593fbc-5a00-563a-a011-c4bcc22fdefd','7858588f-a162-5abc-9ed2-0457e00d7ef0',0,'{"en": "Give every account its own password, stored in a password manager.", "ar": "تمنح كل حساب كلمة مرور خاصة به وتحفظها في مدير كلمات مرور."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('5984f357-1923-5a48-818a-44b56b2c6ba1','7858588f-a162-5abc-9ed2-0457e00d7ef0',1,'{"en": "Change only the forum password, since that is where the breach happened.", "ar": "تغيّر كلمة مرور المنتدى فقط، فهناك حدث التسريب."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('e02d1c2b-017d-57f0-bb03-eec2516eb91d','7858588f-a162-5abc-9ed2-0457e00d7ef0',2,'{"en": "Keep her base password and change one number at the end for each account.", "ar": "تبقي كلمتها الأساسية وتغيّر رقمًا واحدًا في آخرها لكل حساب."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('eb124cec-adaa-55b4-b9b7-d93ad26ab5be','7858588f-a162-5abc-9ed2-0457e00d7ef0',3,'{"en": "Wait and watch for suspicious activity before changing anything.", "ar": "تنتظر وترصد أي نشاط مشبوه قبل أن تغيّر شيئًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('7858588f-a162-5abc-9ed2-0457e00d7ef0','e3593fbc-5a00-563a-a011-c4bcc22fdefd','{"en": {"threat": "Password reuse (credential stuffing)", "lesson": "After a breach, attackers automatically try the leaked password and its small variations on email, shops and banks. Only unique passwords contain the damage, and a password manager makes that practical. Start with email and banking.", "wrong": ["", "Attackers test breached passwords on other sites, so the reused ones stay exposed.", "Predictable variations are guessed by the same tools. Each password must be independent.", "Credential stuffing is automated and usually succeeds long before you notice anything."]}, "ar": {"threat": "إعادة استخدام كلمة المرور (Credential stuffing)", "lesson": "بعد أي تسريب يجرّب المهاجمون كلمة المرور المسرّبة وتعديلاتها البسيطة تلقائيًا على البريد والمتاجر والمصارف. وحدها كلمات المرور الفريدة تحصر الضرر، ومدير كلمات المرور يجعل ذلك عمليًا. ابدأ بالبريد والمصرف.", "wrong": ["", "يختبر المهاجمون كلمات المرور المسرّبة على مواقع أخرى، فتبقى المكررة مكشوفة.", "التعديلات المتوقعة تخمّنها الأدوات نفسها. يجب أن تكون كل كلمة مستقلة.", "هذا الهجوم آلي وينجح عادةً قبل أن تلاحظ أي شيء بوقت طويل."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('f2a61bcd-e098-51a2-b30f-6c717253d3fb',7,2,'d064c943-78d4-52a8-8421-a718b284e08e','{"en": "Karim''s phone buzzes at midnight with a sign-in approval request for his work account, but he is not logging in. Ten minutes later it buzzes again, then again, and a chat message from ''IT support'' asks him to approve one so the alerts stop.", "ar": "يهتز هاتف كريم عند منتصف الليل بطلب موافقة على تسجيل دخول لحساب عمله، وهو لا يسجّل الدخول. بعد عشر دقائق يهتز مجددًا ثم مرة أخرى، وتصله رسالة دردشة من «الدعم التقني» تطلب منه الموافقة على طلب واحد لتتوقف التنبيهات."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('f9f98df8-6140-518f-accf-6bb6799cdbc7','f2a61bcd-e098-51a2-b30f-6c717253d3fb',0,'{"en": "Approve one request so the alerts stop, then change his password in the morning.", "ar": "يوافق على طلب واحد لتتوقف التنبيهات ثم يغيّر كلمة مروره صباحًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('268190ae-debe-5109-9f3d-e1fda918b803','f2a61bcd-e098-51a2-b30f-6c717253d3fb',1,'{"en": "Turn off the phone''s notifications until morning.", "ar": "يوقف إشعارات الهاتف حتى الصباح."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('474038cf-bdc1-5fbb-abe8-51b44d98c5c3','f2a61bcd-e098-51a2-b30f-6c717253d3fb',2,'{"en": "Deny every request, change his password now, and report it to the real IT team.", "ar": "يرفض كل الطلبات، ويغيّر كلمة مروره الآن، ويبلّغ فريق تقنية المعلومات الحقيقي."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('9acd9a9b-090d-5ccf-96ba-8e575c8d16a9','f2a61bcd-e098-51a2-b30f-6c717253d3fb',3,'{"en": "Reply to the chat message and ask the person to confirm they work in IT.", "ar": "يردّ على رسالة الدردشة ويطلب من صاحبها تأكيد أنه يعمل في الدعم التقني."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('f2a61bcd-e098-51a2-b30f-6c717253d3fb','474038cf-bdc1-5fbb-abe8-51b44d98c5c3','{"en": {"threat": "MFA fatigue attack", "lesson": "In an MFA fatigue attack the criminal already knows your password and floods you with prompts, sometimes adding a fake support message, hoping you will approve one. Deny every unexpected prompt, change the password and tell the real IT team.", "wrong": ["Approving gives the attacker immediate access. This is exactly what the flood of prompts is designed to achieve.", "Silencing the phone hides the attack but does not stop it, and the password is probably already known.", "", "The chat message is part of the attack. An identity claim in the same channel proves nothing."]}, "ar": {"threat": "هجوم إرهاق المصادقة (MFA fatigue)", "lesson": "في هذا الهجوم يعرف المجرم كلمة مرورك مسبقًا ويغرقك بطلبات الموافقة، وأحيانًا برسالة دعم مزيّفة، على أمل أن توافق على أحدها. ارفض كل طلب غير متوقع، وغيّر كلمة المرور، وأبلغ فريق التقنية الحقيقي.", "wrong": ["الموافقة تمنح المهاجم دخولًا فوريًا، وهذا بالضبط ما صُمم سيل الطلبات لتحقيقه.", "كتم الهاتف يخفي الهجوم ولا يوقفه، وكلمة المرور غالبًا معروفة أصلًا.", "", "رسالة الدردشة جزء من الهجوم. ادعاء الهوية في القناة نفسها لا يثبت شيئًا."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('f7016c59-68e8-566f-80da-d10bce0f83ad',8,2,'7ef557bd-12ee-5c93-95ec-250804d4d9d5','{"en": "Dana checks her email on a computer in a print shop. As she finishes, she notices a small plastic device between the keyboard cable and the PC that was not there when she arrived.", "ar": "تفحص دانة بريدها الإلكتروني على حاسوب في مطبعة. وعند انتهائها تلاحظ جهازًا بلاستيكيًا صغيرًا بين سلك لوحة المفاتيح والحاسوب لم يكن موجودًا حين وصلت."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('7a732eb0-2f08-5def-b486-b72b57ae07d7','f7016c59-68e8-566f-80da-d10bce0f83ad',0,'{"en": "Log out of her email and clear the browser history before leaving.", "ar": "تسجّل الخروج من بريدها وتمسح سجل التصفح قبل المغادرة."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('c93b62f5-182b-5d2a-839a-6e08ebe5c7fd','f7016c59-68e8-566f-80da-d10bce0f83ad',1,'{"en": "Tell the owner, then check her email again later to see if anything looks odd.", "ar": "تخبر صاحب المحل ثم تعيد فحص بريدها لاحقًا لترى إن كان هناك ما يثير الريبة."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('26823587-7cff-5f52-b86a-aa82da86c493','f7016c59-68e8-566f-80da-d10bce0f83ad',2,'{"en": "Remove the device and take it with her as evidence for the police.", "ar": "تنزع الجهاز وتأخذه معها كدليل."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('4bf66d4a-119d-5034-8352-6189c8f569b9','f7016c59-68e8-566f-80da-d10bce0f83ad',3,'{"en": "Tell the owner, then reset her email password from her own phone.", "ar": "تخبر صاحب المحل ثم تعيد ضبط كلمة مرور بريدها من هاتفها الشخصي."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('f7016c59-68e8-566f-80da-d10bce0f83ad','4bf66d4a-119d-5034-8352-6189c8f569b9','{"en": {"threat": "Credential theft (hardware keylogger)", "lesson": "A hardware keylogger records everything typed on a shared computer, and removing it does not erase what was already recorded. Change the password from a device you trust, review recent sign-ins and turn on MFA so a stolen password is not enough.", "wrong": ["Logging out and clearing history does not undo keystrokes that were already captured.", "Waiting gives the thief time to use the password. Act before anything looks odd.", "Removing the device does not erase what it recorded; her password is still exposed.", ""]}, "ar": {"threat": "سرقة بيانات الدخول (Keylogger مادي)", "lesson": "يسجّل هذا الجهاز كل ما يُكتب على الحاسوب المشترك، ونزعه لا يمحو ما سُجّل. غيّر كلمة المرور من جهاز تثق به، وراجع عمليات الدخول الأخيرة، وفعّل المصادقة متعددة العوامل لتصبح كلمة المرور المسروقة غير كافية.", "wrong": ["تسجيل الخروج ومسح السجل لا يلغيان ما التُقط من ضغطات المفاتيح.", "الانتظار يمنح السارق وقتًا لاستخدام كلمة المرور. تصرّف قبل أن يبدو أي شيء مريبًا.", "نزع الجهاز لا يمحو ما سجّله؛ كلمة مرورها ما زالت مكشوفة.", ""]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('c3f9824a-432b-5cb9-98a4-fcd83ac91fd5',9,2,'91e04571-f3ff-5ce2-9ffa-75aa4bf4c416','{"en": "At a small office, a man in a courier jacket says he is from the IT contractor and has a ticket to fix the Wi-Fi. He carries a laptop and asks Reem, the receptionist, to let him into the server closet and to give him the admin password. He is polite and knows her manager''s first name.", "ar": "في مكتب صغير، يقول رجل يرتدي سترة مندوب توصيل إنه من شركة الصيانة التقنية ومعه طلب إصلاح للواي فاي. يحمل حاسوبًا ويطلب من ريم، موظفة الاستقبال، أن تدخله غرفة الخوادم وتعطيه كلمة مرور المسؤول. هو مهذب ويعرف الاسم الأول لمديرها."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('08e5dee3-00e1-53de-9be1-2aa60acee29e','c3f9824a-432b-5cb9-98a4-fcd83ac91fd5',0,'{"en": "Let him in, but stay nearby and watch what he does during the visit.", "ar": "تدخله لكنها تبقى قريبة لتراقب ما يفعله."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('586af200-bb82-57d3-805f-575248b5a7c5','c3f9824a-432b-5cb9-98a4-fcd83ac91fd5',1,'{"en": "Ask him to wait while she checks with her manager or the IT firm.", "ar": "تطلب منه الانتظار بينما تتأكد من مديرها أو من شركة الصيانة."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('ada11391-3622-59cf-9477-0e8cc8e55de8','c3f9824a-432b-5cb9-98a4-fcd83ac91fd5',2,'{"en": "Give him the guest Wi-Fi password only and keep the server closet locked.", "ar": "تعطيه كلمة مرور شبكة الضيوف فقط وتبقي غرفة الخوادم مقفلة."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('46e09627-5865-5abd-aeaf-62c695df0906','c3f9824a-432b-5cb9-98a4-fcd83ac91fd5',3,'{"en": "Ask to see his ID card and let him in if it looks professional.", "ar": "تطلب رؤية بطاقته وتدخله إن بدت احترافية."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('c3f9824a-432b-5cb9-98a4-fcd83ac91fd5','586af200-bb82-57d3-805f-575248b5a7c5','{"en": {"threat": "Social engineering (pretexting)", "lesson": "Pretexting wins trust with a uniform, a polite manner and a few real names. A visitor with a ticket should be confirmed with the company or manager through a number you already hold. Politeness is not verification.", "wrong": ["Watching does not stop a quick plug-in or a photo. Access should not be granted before verification.", "", "Any access given to an unverified person is the foothold he is after.", "ID cards are easy to fake. Verification has to come from the company through a channel you already trust."]}, "ar": {"threat": "الهندسة الاجتماعية (انتحال الصفة)", "lesson": "ينال المنتحل الثقة بزي رسمي وأسلوب مهذب وبضعة أسماء حقيقية. يجب تأكيد زائر معه طلب عمل من الشركة أو المدير عبر رقم تملكه مسبقًا. اللباقة ليست وسيلة تحقق.", "wrong": ["المراقبة لا تمنع توصيلًا سريعًا لجهاز أو التقاط صورة. لا يُمنح الوصول قبل التحقق.", "", "أي وصول يُمنح لشخص لم يُتحقق منه هو موطئ القدم الذي يسعى إليه.", "بطاقات الهوية يسهل تزويرها. التحقق يجب أن يأتي من الشركة عبر قناة تثق بها."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('3610196c-cc52-5907-91a1-beb038c2cc9e',10,2,'28a52b05-cc35-5c72-a4c2-c42f361a2e57','{"en": "Mariam has just booked a trip and wants to share her excitement. Her draft post has a photo of her boarding pass, her home city tagged, and the line ''House empty for two weeks!'' Her account is public.", "ar": "حجزت مريم رحلة للتو وتريد مشاركة حماسها. مسودة منشورها تضم صورة بطاقة الصعود إلى الطائرة، ووسم مدينتها، وعبارة «البيت فارغ لأسبوعين!». حسابها عام."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('f3cab8b7-ba55-5087-aca2-c7c1adc9640f','3610196c-cc52-5907-91a1-beb038c2cc9e',0,'{"en": "Post it, but blur the passenger name on the boarding pass.", "ar": "تنشره لكنها تطمس اسمها على بطاقة الصعود."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('c616b679-fb2d-509b-99bf-7f66e20effc7','3610196c-cc52-5907-91a1-beb038c2cc9e',1,'{"en": "Post it to ''close friends'' only, keeping the same details and photo.", "ar": "تنشره للأصدقاء المقرّبين فقط بالتفاصيل نفسها."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('28a5d5a5-d382-5b35-9756-d5367362990d','3610196c-cc52-5907-91a1-beb038c2cc9e',2,'{"en": "Share the photos after the trip, without the boarding pass.", "ar": "تشارك الصور بعد الرحلة دون بطاقة الصعود."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('858ffd6d-e6ad-5153-b3fb-798e1347bf8f','3610196c-cc52-5907-91a1-beb038c2cc9e',3,'{"en": "Post it as drafted, but switch off the location tagging feature.", "ar": "تنشره كما هو مع إيقاف وسم الموقع."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('3610196c-cc52-5907-91a1-beb038c2cc9e','28a5d5a5-d382-5b35-9756-d5367362990d','{"en": {"threat": "Oversharing", "lesson": "Boarding-pass barcodes contain booking data, and travel dates plus ''house empty'' announce an opportunity to burglars and scammers. Share trips afterwards, and keep documents, tickets and exact dates out of photos.", "wrong": ["The barcode still holds booking details, and the post still announces an empty house.", "Screenshots travel beyond any friends list, and the boarding pass and empty house are still exposed.", "", "Without the tag, her city, dates and empty house are still public."]}, "ar": {"threat": "الإفراط في المشاركة (Oversharing)", "lesson": "يحمل رمز بطاقة الصعود بيانات الحجز، وتواريخ السفر مع «البيت فارغ» تعلن فرصة للصوص والمحتالين. شارك الرحلات بعد انتهائها، وأبقِ الوثائق والتذاكر والتواريخ الدقيقة خارج الصور.", "wrong": ["الرمز ما زال يحمل بيانات الحجز، والمنشور ما زال يعلن أن البيت فارغ.", "لقطات الشاشة تنتقل خارج أي قائمة أصدقاء، وتبقى بطاقة الصعود والبيت الفارغ مكشوفين.", "", "من دون الوسم، تبقى مدينتها وتواريخها وبيتها الفارغ معلنة للجميع."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('e472e785-50f0-5365-b6d2-f2dc8df89cdc',11,3,'e54b6021-cb80-5bab-b6d9-1887a9b98d4e','{"en": "At the airport Hani sees two open networks, ''Airport_Free_WiFi'' and ''Airport Free WiFi 2''. He needs to check his bank balance before boarding.", "ar": "في المطار يرى هاني شبكتين مفتوحتين: «Airport_Free_WiFi» و«Airport Free WiFi 2». يحتاج إلى معرفة رصيده المصرفي قبل الصعود إلى الطائرة."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('f4d842d1-bece-5d40-a670-0b5e988aa133','e472e785-50f0-5365-b6d2-f2dc8df89cdc',0,'{"en": "Join the one with the stronger signal and use the bank''s app, which encrypts its traffic.", "ar": "ينضم إلى الأقوى إشارة ويستخدم تطبيق المصرف الذي يشفّر بياناته."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('408e50c1-72f4-590e-b35f-3b34c0b41449','e472e785-50f0-5365-b6d2-f2dc8df89cdc',1,'{"en": "Join either one and stay logged out of everything except the bank.", "ar": "ينضم إلى أي منهما ويبقى خارج كل الحسابات عدا المصرف."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('c3650839-1ff4-530d-862e-e51d1f5c19d1','e472e785-50f0-5365-b6d2-f2dc8df89cdc',2,'{"en": "Join either one and switch on a free VPN app he finds in the app store.", "ar": "ينضم إلى أي منهما ويشغّل تطبيق VPN مجانيًا وجده في المتجر."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('0d4a2c8e-f663-5770-b200-75c75d771028','e472e785-50f0-5365-b6d2-f2dc8df89cdc',3,'{"en": "Use his own mobile data for the bank and leave the airport networks alone.", "ar": "يستخدم بيانات هاتفه للمصرف ويترك شبكات المطار."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('e472e785-50f0-5365-b6d2-f2dc8df89cdc','0d4a2c8e-f663-5770-b200-75c75d771028','{"en": {"threat": "Public Wi-Fi risk (evil twin)", "lesson": "Attackers set up look-alike networks, known as evil twins, to sit between you and the internet. When you handle money or sensitive accounts, your own mobile data is a safer path than any open network.", "wrong": ["Encryption helps, but a fake network can still interfere and capture other data. A safer option exists.", "Being logged out elsewhere does not protect the bank session on an unverified network.", "An unknown free VPN may log or sell your traffic, so it can be the interceptor itself.", ""]}, "ar": {"threat": "خطر الواي فاي العام (التوأم الشرير)", "lesson": "ينشئ المهاجمون شبكات مشابهة، تُعرف بالتوأم الشرير، لتقف بينك وبين الإنترنت. عند التعامل مع المال أو الحسابات الحساسة تكون بيانات هاتفك أأمن من أي شبكة مفتوحة.", "wrong": ["التشفير يفيد، لكن الشبكة المزيّفة قد تتدخل وتلتقط بيانات أخرى. وهناك خيار أأمن.", "الخروج من الحسابات الأخرى لا يحمي جلسة المصرف على شبكة لم يُتحقق منها.", "تطبيق VPN مجهول قد يسجّل بياناتك أو يبيعها، فقد يكون هو المتنصّت.", ""]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('065d3dc7-c9eb-5b0e-8bdd-58d17f3ccdfd',12,3,'c9076d9b-d5b5-5a7c-9ec8-4e091216d7e5','{"en": "At a café, Laila signs in to her university''s course site on the café''s open Wi-Fi. The browser shows ''Not secure'' beside the address, which starts with http:// instead of https://.", "ar": "في مقهى، تسجّل ليلى الدخول إلى موقع مقررات جامعتها عبر واي فاي المقهى المفتوح. يعرض المتصفح عبارة «غير آمن» بجوار العنوان الذي يبدأ بـ http:// بدل https://."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('2429ddff-bf3d-53ff-83c8-d9cbb0395d74','065d3dc7-c9eb-5b0e-8bdd-58d17f3ccdfd',0,'{"en": "Stop, switch to mobile data, and log in only when the address uses https://.", "ar": "تتوقف وتنتقل إلى بيانات هاتفها ولا تسجّل الدخول إلا حين يبدأ العنوان بـ https://."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('dcd8e787-c9f0-56ee-bf3c-750593ee18b4','065d3dc7-c9eb-5b0e-8bdd-58d17f3ccdfd',1,'{"en": "Continue, since she is only checking course notes, not making payments.", "ar": "تتابع، فهي تطّلع على ملاحظات المقرر فقط ولا تدفع شيئًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('1a00e6af-84e1-57c2-a5c6-7b99b9000d5e','065d3dc7-c9eb-5b0e-8bdd-58d17f3ccdfd',2,'{"en": "Continue after refreshing the page, as the label sometimes appears by mistake.", "ar": "تتابع بعد تحديث الصفحة، فالتنبيه يظهر أحيانًا بالخطأ."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('9ee55fc0-d946-5812-9b42-61f8fb58aa41','065d3dc7-c9eb-5b0e-8bdd-58d17f3ccdfd',3,'{"en": "Continue in a private window so the session is not stored.", "ar": "تتابع في نافذة تصفح خاص حتى لا تُحفظ الجلسة."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('065d3dc7-c9eb-5b0e-8bdd-58d17f3ccdfd','2429ddff-bf3d-53ff-83c8-d9cbb0395d74','{"en": {"threat": "Network sniffing", "lesson": "On http:// sites, data travels unencrypted, so anyone on the same open network can read it with simple sniffing tools. Use https:// for logins or switch networks. A private window only hides history on your own device.", "wrong": ["", "Her login details would travel in readable form, and passwords are often reused on other services.", "The label is accurate. Refreshing does not add encryption.", "A private window hides history on her device, not the traffic on the network."]}, "ar": {"threat": "التنصّت على الشبكة (Sniffing)", "lesson": "في مواقع http:// تنتقل البيانات دون تشفير، فيستطيع أي شخص على الشبكة المفتوحة نفسها قراءتها بأدوات بسيطة. استخدم https:// لتسجيل الدخول أو غيّر الشبكة. التصفح الخاص يخفي السجل على جهازك فقط.", "wrong": ["", "ستنتقل بيانات دخولها بشكل مقروء، وكثيرًا ما تُستخدم كلمات المرور نفسها في خدمات أخرى.", "التنبيه صحيح. وتحديث الصفحة لا يضيف تشفيرًا.", "التصفح الخاص يخفي السجل على جهازها، لا الحركة على الشبكة."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('d84d3e5a-3a9b-56c0-9c93-a8fd85e1a507',13,3,'92c195f4-e8f0-5e6e-91f8-80f35a544987','{"en": "In a hotel, Adel opens his bank''s website on the hotel Wi-Fi. His browser blocks the page with a warning that the site''s security certificate does not match the address, and offers an ''Advanced: proceed anyway'' link. The same site loaded without any warning on his mobile data yesterday.", "ar": "في فندق، يفتح عادل موقع مصرفه عبر واي فاي الفندق. يحجب المتصفح الصفحة بتحذير من أن شهادة أمان الموقع لا تطابق العنوان، ويعرض رابط «متقدم: المتابعة على أي حال». وكان الموقع نفسه يعمل دون أي تحذير أمس على بيانات هاتفه."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('6e4129d1-47c2-559a-9951-4f614205beee','d84d3e5a-3a9b-56c0-9c93-a8fd85e1a507',0,'{"en": "Proceed anyway, since the bank''s address is spelled correctly in the bar.", "ar": "يتابع على أي حال، فعنوان المصرف مكتوب بشكل صحيح."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('b939a9be-e412-5d07-8825-3e820ad8fd50','d84d3e5a-3a9b-56c0-9c93-a8fd85e1a507',1,'{"en": "Stop, switch to mobile data, and tell the bank about the warning.", "ar": "يتوقف، وينتقل إلى بيانات هاتفه، ويبلّغ المصرف بالتحذير."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('f25b37d0-ffcd-59d1-b92f-47318011a4d5','d84d3e5a-3a9b-56c0-9c93-a8fd85e1a507',2,'{"en": "Reload the page a few times to see if the warning goes away by itself.", "ar": "يعيد تحميل الصفحة عدة مرات ليرى إن كان التحذير سيختفي."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('1c7e8eeb-ab9e-52c1-81f8-a9beb07d0cf5','d84d3e5a-3a9b-56c0-9c93-a8fd85e1a507',3,'{"en": "Proceed and log in, but avoid making any transfers or payments.", "ar": "يتابع ويسجّل الدخول لكنه لا يجري أي تحويلات."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('d84d3e5a-3a9b-56c0-9c93-a8fd85e1a507','b939a9be-e412-5d07-8825-3e820ad8fd50','{"en": {"threat": "Man-in-the-middle attack", "lesson": "A certificate warning on a site that worked yesterday suggests someone may be intercepting the connection. Clicking through hands over your login. Leave the network, use mobile data and tell the bank.", "wrong": ["A correct spelling is not the issue. A mismatch on a site that was fine yesterday points to interception.", "", "Reloading does not change the cause. A persistent warning is a red flag.", "Logging in alone gives an interceptor your credentials and session, even with no transfers."]}, "ar": {"threat": "هجوم الوسيط (Man-in-the-middle)", "lesson": "ظهور تحذير شهادة في موقع كان يعمل أمس يوحي بأن أحدًا قد يعترض الاتصال. والمتابعة رغم التحذير تسلّم بيانات دخولك. غادر الشبكة، واستخدم بيانات هاتفك، وأبلغ المصرف.", "wrong": ["صحة الإملاء ليست المشكلة. عدم التطابق في موقع كان سليمًا أمس يشير إلى اعتراض.", "", "إعادة التحميل لا تغيّر السبب. والتحذير المستمر علامة خطر.", "تسجيل الدخول وحده يعطي المعترِض بياناتك وجلستك، حتى دون أي تحويلات."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('b964113e-2c2c-52c0-8270-dec4880e0148',14,3,'e80e6e0b-b90f-5211-a503-4a2484dcddcb','{"en": "Rania needs to edit a PDF urgently. A search result offers ''PDF Editor Pro, full version free, no licence needed'' on a site she has never heard of. It downloads an installer, and Windows asks permission to make changes to her device.", "ar": "تحتاج رانيا إلى تعديل ملف PDF بشكل عاجل. تعرض لها نتيجة بحث «محرر PDF برو، النسخة الكاملة مجانًا دون ترخيص» على موقع لم تسمع به من قبل. ينزل مثبّت، ويطلب ويندوز إذنها لإجراء تغييرات على جهازها."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('fb24b34e-b89c-59cd-8f9e-e2c21f40739b','b964113e-2c2c-52c0-8270-dec4880e0148',0,'{"en": "Allow it, since her antivirus is running and would block anything dangerous.", "ar": "تسمح به، فمضاد الفيروسات يعمل وسيحجب أي شيء خطير."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('c06094a0-9738-532e-bb0f-59cbfa840f17','b964113e-2c2c-52c0-8270-dec4880e0148',1,'{"en": "Allow it, but disconnect from the internet while it installs.", "ar": "تسمح به لكنها تقطع الإنترنت أثناء التثبيت."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('55db296b-ce3f-5eb8-9bfb-f797ce41ca26','b964113e-2c2c-52c0-8270-dec4880e0148',2,'{"en": "Allow it, and uninstall it if the computer starts running slowly.", "ar": "تسمح به وتزيله إذا بدأ الحاسوب يعمل ببطء."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('832dcedc-4911-52f9-b49b-3dae1db45ebd','b964113e-2c2c-52c0-8270-dec4880e0148',3,'{"en": "Cancel it and use a legitimate editor, even if the free version is limited.", "ar": "تلغيه وتستخدم محررًا شرعيًا حتى لو كانت نسخته المجانية محدودة."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('b964113e-2c2c-52c0-8270-dec4880e0148','832dcedc-4911-52f9-b49b-3dae1db45ebd','{"en": {"threat": "Malware (cracked software)", "lesson": "Free ''full versions'' of paid software are a favourite way to spread info-stealers and remote-access trojans. Antivirus is a safety net, not permission. Use a trusted vendor, even if the free version is limited.", "wrong": ["Antivirus is not perfect, and cracked installers are often built to evade it.", "Installing offline still installs the malware; it activates when she reconnects.", "Many threats run silently. Slowness is rarely the sign, and data may be gone by then.", ""]}, "ar": {"threat": "البرمجيات الخبيثة (البرامج المقرصنة)", "lesson": "النسخ «الكاملة» المجانية من البرامج المدفوعة وسيلة مفضلة لنشر برمجيات سرقة البيانات والتحكم عن بُعد. مضاد الفيروسات شبكة أمان وليس إذنًا. استخدم مصدرًا موثوقًا حتى لو كانت النسخة المجانية محدودة.", "wrong": ["مضاد الفيروسات ليس معصومًا، ومثبّتات البرامج المقرصنة تُصمم غالبًا لتفاديه.", "التثبيت دون إنترنت يثبّت البرمجية الخبيثة أيضًا، وتنشط عند إعادة الاتصال.", "كثير من التهديدات يعمل بصمت. والبطء نادرًا ما يكون العلامة، وقد تضيع البيانات قبلها.", ""]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('aec1bd3b-a930-5ccf-9c96-8145139d183b',15,3,'c4ac4a59-8f2a-55bd-8559-bfe95acb537f','{"en": "Yacine finds a USB flash drive in the car park outside his office. It has a label reading ''Salary Review 2026 - Confidential''. He is curious whose it is.", "ar": "يجد ياسين قرص USB في موقف السيارات أمام مكتبه. عليه ملصق مكتوب فيه «مراجعة الرواتب 2026 - سري». يتساءل بدافع الفضول لمن هو."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('f24a1311-da88-5117-8317-a8cd9b85eeec','aec1bd3b-a930-5ccf-9c96-8145139d183b',0,'{"en": "Hand it to the IT or security team without plugging it in anywhere.", "ar": "يسلّمه لفريق تقنية المعلومات أو الأمن دون توصيله بأي جهاز."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('f0d7dba7-1eee-57e9-9924-eca095fd81c4','aec1bd3b-a930-5ccf-9c96-8145139d183b',1,'{"en": "Plug it into an old personal laptop that has nothing important on it.", "ar": "يوصله بحاسوب شخصي قديم لا يحوي شيئًا مهمًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('fdfb142d-c2dc-50b6-b1c1-ea85dc4adc6b','aec1bd3b-a930-5ccf-9c96-8145139d183b',2,'{"en": "Plug it into his work computer so the antivirus can scan it automatically.", "ar": "يوصله بحاسوب العمل ليفحصه مضاد الفيروسات تلقائيًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('2e0d7989-addf-51d5-a5ac-fa6774883a6f','aec1bd3b-a930-5ccf-9c96-8145139d183b',3,'{"en": "Leave it where he found it so the owner can come back for it.", "ar": "يتركه حيث وجده ليعود صاحبه ويأخذه."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('aec1bd3b-a930-5ccf-9c96-8145139d183b','f24a1311-da88-5117-8317-a8cd9b85eeec','{"en": {"threat": "USB baiting", "lesson": "Attackers drop tempting USB drives because curiosity does the work. A plugged-in drive can act as a keyboard and run commands within seconds. Give it to the security team unplugged so they can handle it safely.", "wrong": ["", "Some devices act as keyboards and run commands at once, and the old laptop may still be signed in to accounts or your home network.", "Some attacks act the moment the device connects, before any scan, and this is a company network.", "Leaving it means someone else may plug it in, and a drive dropped at your office may be targeting it."]}, "ar": {"threat": "الطُّعم عبر USB (USB baiting)", "lesson": "يترك المهاجمون أقراص USB مغرية لأن الفضول يؤدي المهمة. القرص الموصول قد يتصرف كلوحة مفاتيح وينفذ أوامر خلال ثوانٍ. سلّمه لفريق الأمن دون توصيله ليتعاملوا معه بأمان.", "wrong": ["", "بعض الأجهزة تتصرف كلوحات مفاتيح وتنفذ أوامر فورًا، وقد يكون الحاسوب القديم مسجّلًا دخوله إلى حسابات أو إلى شبكة منزلك.", "بعض الهجمات يعمل لحظة التوصيل قبل أي فحص، وهذه شبكة الشركة.", "تركه قد يدفع شخصًا آخر لتوصيله، وقرص أُسقط عند مكتبك قد يكون موجّهًا إليه."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('11b0620e-d0bc-586f-bf1e-888b84bf3400',16,4,'b4b08b5d-6a7f-5b42-8c42-0c57f8f3f749','{"en": "A city car park has a new sticker on its parking meter: ''Pay by QR code and avoid fines.'' Sarah notices the sticker is slightly raised at the edges and the other meters do not have one. When she scans it, her phone previews a web address she does not recognise, not the city council''s.", "ar": "في موقف سيارات بالمدينة ملصق جديد على عدّاد الوقوف: «ادفع عبر رمز QR وتجنّب المخالفات». تلاحظ سارة أن الملصق مرتفع قليلًا عند أطرافه وأن العدّادات الأخرى خالية منه. وعندما تمسحه، يعرض هاتفها معاينة لعنوان موقع لا تعرفه وليس عنوان البلدية."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('f930a120-ec9c-5413-a5de-080df4aa0819','11b0620e-d0bc-586f-bf1e-888b84bf3400',0,'{"en": "Continue to the page, since the sticker is on an official-looking meter.", "ar": "تتابع إلى الصفحة، فالملصق على عدّاد يبدو رسميًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('1fdd4130-5975-5b9a-a5d3-3f9016d22beb','11b0620e-d0bc-586f-bf1e-888b84bf3400',1,'{"en": "Continue, but pay with a prepaid card to limit any loss.", "ar": "تتابع لكنها تدفع ببطاقة مدفوعة مسبقًا للحد من الخسارة."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('1bc499d9-9760-5c4e-be4d-2c5120f664fc','11b0620e-d0bc-586f-bf1e-888b84bf3400',2,'{"en": "Skip it, pay via the council''s app or a machine, and report the sticker.", "ar": "لا تفتحه، وتدفع عبر تطبيق البلدية أو جهاز الدفع، وتبلّغ عن الملصق."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('f027c56a-7aaa-571c-8874-1f400fc86af0','11b0620e-d0bc-586f-bf1e-888b84bf3400',3,'{"en": "Open the page and check for the padlock icon before entering card details.", "ar": "تفتح الصفحة وتتحقق من أيقونة القفل قبل إدخال بيانات البطاقة."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('11b0620e-d0bc-586f-bf1e-888b84bf3400','1bc499d9-9760-5c4e-be4d-2c5120f664fc','{"en": {"threat": "QR-code phishing (quishing)", "lesson": "A QR code hides its destination, so criminals stick fake ones over real ones. Preview the link, and when it looks wrong, pay through the official app or machine. The padlock only means the connection is encrypted, not that the site is honest.", "wrong": ["Fake codes are stuck over genuine ones. Where a sticker sits proves nothing.", "Limiting the amount does not stop her card data being captured and reused.", "", "Scam sites have padlocks too. It shows encryption, not honesty."]}, "ar": {"threat": "التصيّد عبر رموز QR (Quishing)", "lesson": "رمز QR يخفي وجهته، لذا يلصق المجرمون رموزًا مزيّفة فوق الحقيقية. عاين الرابط، وإذا بدا غريبًا فادفع عبر التطبيق أو الجهاز الرسمي. القفل يعني أن الاتصال مشفّر فقط، لا أن الموقع صادق.", "wrong": ["تُلصق الرموز المزيّفة فوق الحقيقية. ومكان الملصق لا يثبت شيئًا.", "تقليل المبلغ لا يمنع التقاط بيانات بطاقتها وإعادة استخدامها.", "", "مواقع الاحتيال لها أقفال أيضًا. القفل يدل على التشفير لا على الصدق."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('f6cf95eb-1966-5b25-abe3-185fc650ae08',17,4,'f45189f5-84a2-538b-968b-75c2d58f37b7','{"en": "Tariq is a finance officer. An email apparently from the CEO asks him to pay a new supplier by transfer today and to keep it confidential because the deal is still in progress. It mentions a real meeting from last week. Looking closely, the sender''s address ends in ''@acmecorp-finance.com'', whereas the company uses ''@acmecorp.com''.", "ar": "طارق موظف في القسم المالي. يصله بريد يبدو أنه من المدير التنفيذي يطلب فيه دفع مبلغ لمورّد جديد بتحويل اليوم، مع إبقاء الأمر سريًا لأن الصفقة لم تكتمل. ويذكر اجتماعًا حقيقيًا جرى الأسبوع الماضي. وعند التدقيق ينتهي عنوان المرسل بـ acmecorp-finance.com@ بينما تستخدم الشركة acmecorp.com@."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('4e34b3e1-52bb-59b6-87d0-fd1bde5916ba','f6cf95eb-1966-5b25-abe3-185fc650ae08',0,'{"en": "Reply to the email and ask the CEO for the supplier''s invoice before paying.", "ar": "يردّ على البريد ويطلب من المدير فاتورة المورّد قبل الدفع."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('107132aa-78a3-5231-a765-8d086c325006','f6cf95eb-1966-5b25-abe3-185fc650ae08',1,'{"en": "Make a small test payment first to see whether the account is genuine.", "ar": "يجري دفعة تجريبية صغيرة أولًا ليرى إن كان الحساب حقيقيًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('3a1e5c72-d7e3-52dd-9b7f-c754bc33675f','f6cf95eb-1966-5b25-abe3-185fc650ae08',2,'{"en": "Pay it, but ask the CEO''s assistant to approve it by email first.", "ar": "يدفع لكنه يطلب من مساعد المدير الموافقة عبر البريد."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('2f35927e-beb2-5097-bce7-25082b78dc66','f6cf95eb-1966-5b25-abe3-185fc650ae08',3,'{"en": "Call the CEO on a known number and follow the payment approval process.", "ar": "يتصل بالمدير على رقم معروف ويتبع إجراءات الموافقة على الدفع."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('f6cf95eb-1966-5b25-abe3-185fc650ae08','2f35927e-beb2-5097-bce7-25082b78dc66','{"en": {"threat": "Spear phishing and domain impersonation", "lesson": "Spear phishing is aimed at one person''s role, using a look-alike domain, authority, secrecy and real details. Payment requests should be confirmed through a separate channel, such as a call to a known number, and follow approval rules regardless of who asks.", "wrong": ["Your reply goes to the attacker, who will send a convincing fake invoice.", "A test payment still sends money to the fraudster and builds trust for a larger request.", "An approval by email stays inside the same fake or spoofed channel.", ""]}, "ar": {"threat": "التصيّد الموجّه وانتحال النطاق (Spear phishing)", "lesson": "يستهدف التصيّد الموجّه دور شخص بعينه عبر نطاق مشابه وسلطة وسرّية وتفاصيل حقيقية. يجب تأكيد طلبات الدفع عبر قناة مستقلة، مثل مكالمة على رقم معروف، واتباع إجراءات الموافقة مهما كان الطالب.", "wrong": ["ردّك يصل إلى المهاجم الذي سيرسل فاتورة مزوّرة مقنعة.", "الدفعة التجريبية ترسل المال إلى المحتال وتبني الثقة لطلب أكبر.", "الموافقة بالبريد تبقى داخل القناة المزيّفة أو المنتحلة نفسها.", ""]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('8f12ee3c-2b99-5970-9dde-36e558a35043',18,4,'473acc42-0da0-54ed-824e-4d7d2ac319bc','{"en": "On Monday morning, Hala''s computer shows a message saying her files are locked and demanding a cryptocurrency payment within 48 hours. The computer is connected to the office network and shared drive, and the office backups sit on a drive that is also connected.", "ar": "صباح الاثنين، يعرض حاسوب هالة رسالة تقول إن ملفاتها مقفلة وتطلب دفعًا بالعملة الرقمية خلال 48 ساعة. الحاسوب متصل بشبكة المكتب والقرص المشترك، والنسخ الاحتياطية للمكتب على قرص متصل أيضًا."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('c28558a2-c43d-5c0c-913c-b8006952d6aa','8f12ee3c-2b99-5970-9dde-36e558a35043',0,'{"en": "Unplug the network cable or turn off Wi-Fi, don''t pay, and call IT now.", "ar": "تفصل كابل الشبكة أو توقف الواي فاي، ولا تدفع، وتتصل بفريق التقنية فورًا."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('f48d8233-6770-586f-a357-a6626f6e5513','8f12ee3c-2b99-5970-9dde-36e558a35043',1,'{"en": "Restart the computer to see if the message disappears, then try opening her files.", "ar": "تعيد تشغيل الحاسوب لترى إن كانت الرسالة ستختفي ثم تحاول فتح ملفاتها."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('028ea97c-522e-5599-9f68-33a43bf5f6b5','8f12ee3c-2b99-5970-9dde-36e558a35043',2,'{"en": "Pay the ransom quickly since the deadline is short and the amount is modest.", "ar": "تدفع الفدية بسرعة فالمهلة قصيرة والمبلغ معقول."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('904cc8d9-5ccd-59cb-95d9-3170d92290b6','8f12ee3c-2b99-5970-9dde-36e558a35043',3,'{"en": "Delete the ransom note and start restoring files from the connected backup drive.", "ar": "تحذف رسالة الفدية وتبدأ استعادة الملفات من قرص النسخ الاحتياطي المتصل."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('8f12ee3c-2b99-5970-9dde-36e558a35043','c28558a2-c43d-5c0c-913c-b8006952d6aa','{"en": {"threat": "Ransomware", "lesson": "The first minutes decide the damage. Disconnect the machine to stop spread, do not pay (it funds criminals and guarantees nothing), leave the machine as it is for investigators, and let IT restore from clean, isolated backups.", "wrong": ["", "Restarting can trigger further encryption and destroys evidence while the infection keeps spreading.", "Payment guarantees nothing, funds criminals and marks you as a payer, while the infection remains.", "A connected backup can be encrypted too, and restoring before containment can reinfect everything."]}, "ar": {"threat": "برمجيات الفدية (Ransomware)", "lesson": "الدقائق الأولى تحدد حجم الضرر. افصل الجهاز لوقف الانتشار، ولا تدفع (فالدفع يموّل المجرمين ولا يضمن شيئًا)، واترك الجهاز كما هو للمحققين، ودع فريق التقنية يستعيد من نسخ احتياطية نظيفة ومعزولة.", "wrong": ["", "إعادة التشغيل قد تطلق مزيدًا من التشفير وتُتلف الأدلة بينما تواصل العدوى انتشارها.", "الدفع لا يضمن شيئًا ويموّل المجرمين ويضعك في قائمة الدافعين، والعدوى باقية.", "النسخة الاحتياطية المتصلة قد تُشفَّر أيضًا، والاستعادة قبل الاحتواء قد تعيد العدوى إلى كل شيء."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('0e6b3078-86cc-5100-adbb-93d9393f459c',19,4,'5d5cb559-db54-5ac7-9b78-c60038d7eb06','{"en": "Ines installed a free ''coupon finder'' browser extension. A week later her online shop account sends an alert about a sign-in from another country, even though she never shared her password and her account uses multi-factor authentication that was never prompted.", "ar": "ثبّتت إينيس إضافة مجانية للمتصفح لـ«إيجاد القسائم». بعد أسبوع يرسل حسابها في المتجر الإلكتروني تنبيهًا بتسجيل دخول من بلد آخر، رغم أنها لم تشارك كلمة مرورها وأن حسابها يستخدم مصادقة متعددة العوامل لم تُطلب منها."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('882ace84-66a6-5420-bd8b-52ca72aa68f9','0e6b3078-86cc-5100-adbb-93d9393f459c',0,'{"en": "Change only the account password, since that is what blocks the intruder.", "ar": "تغيّر كلمة مرور الحساب فقط، فهذا يمنع المتسلل."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('838b2459-0913-5958-8314-6767bc1ef1d1','0e6b3078-86cc-5100-adbb-93d9393f459c',1,'{"en": "Add a stronger MFA method and keep using the extension as before.", "ar": "تضيف وسيلة مصادقة أقوى وتواصل استخدام الإضافة."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('a97a21c8-7c47-5411-b250-f170d95674a8','0e6b3078-86cc-5100-adbb-93d9393f459c',2,'{"en": "Remove the extension, end every session, then change her passwords.", "ar": "تزيل الإضافة، وتُنهي كل الجلسات، ثم تغيّر كلمات مرورها."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('34fc2976-3200-5d75-8157-df79896f54c0','0e6b3078-86cc-5100-adbb-93d9393f459c',3,'{"en": "Log out on her own computer and carry on using the shop as before.", "ar": "تسجّل الخروج على حاسوبها وتواصل كما كانت."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('0e6b3078-86cc-5100-adbb-93d9393f459c','a97a21c8-7c47-5411-b250-f170d95674a8','{"en": {"threat": "Session hijacking (cookie theft)", "lesson": "Malicious extensions can steal session cookies, which prove you are already signed in, so the attacker bypasses both password and MFA. Remove the extension, sign out everywhere to cancel sessions, then change passwords from a clean device.", "wrong": ["A stolen session often stays valid after a password change unless all sessions are revoked.", "MFA does not help once a session is already authenticated, and the extension keeps capturing.", "", "Logging out locally does not end the attacker''s session on the server, and the extension remains."]}, "ar": {"threat": "اختطاف الجلسات (سرقة ملفات تعريف الجلسة)", "lesson": "قد تسرق الإضافات الخبيثة ملفات الجلسة التي تثبت أنك مسجّل دخولك مسبقًا، فيتجاوز المهاجم كلمة المرور والمصادقة معًا. أزل الإضافة، وأنهِ الجلسات في كل مكان، ثم غيّر كلمات المرور من جهاز نظيف.", "wrong": ["الجلسة المسروقة تبقى غالبًا صالحة بعد تغيير كلمة المرور ما لم تُلغَ كل الجلسات.", "المصادقة لا تفيد بعد أن تصبح الجلسة موثّقة، والإضافة تواصل الالتقاط.", "", "تسجيل الخروج محليًا لا ينهي جلسة المهاجم على الخادم، والإضافة باقية."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
insert into public.questions(id,position,stage,category_id,scenario) values ('7b0cfcee-b32c-5852-a255-5669ba40fe74',20,4,'27e717a1-ea9a-56f9-8446-a99cb07f9a49','{"en": "Moments after entering her work credentials on a page reached through a delivery-notice email, Laith realises the page was fake. Nothing seems to have happened and no one has noticed. His account has access to client files, and he worries he will be blamed.", "ar": "بعد لحظات من إدخال بيانات عمله في صفحة وصل إليها عبر بريد «إشعار توصيل»، يدرك ليث أن الصفحة مزيّفة. لا يبدو أن شيئًا حدث ولم يلاحظ أحد. حسابه يتيح الوصول إلى ملفات العملاء، وهو قلق من أن يُلام."}'::jsonb) on conflict (id) do update set scenario=excluded.scenario, stage=excluded.stage, category_id=excluded.category_id;
insert into public.options(id,question_id,position,label) values ('e6a1dc25-cc06-51f7-9e2a-48f53737a268','7b0cfcee-b32c-5852-a255-5669ba40fe74',0,'{"en": "Change his password at once and tell no one, since the matter is closed.", "ar": "يغيّر كلمة مروره فورًا ولا يخبر أحدًا، فالأمر انتهى."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('1dd9589a-12cd-5e3d-afa2-15f03f746d42','7b0cfcee-b32c-5852-a255-5669ba40fe74',1,'{"en": "Report it to the security team now and change his password as advised.", "ar": "يبلّغ فريق الأمن فورًا ويغيّر كلمة مروره بحسب إرشاداتهم."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('149a71b0-48a1-59ba-aa39-86512cb3e79f','7b0cfcee-b32c-5852-a255-5669ba40fe74',2,'{"en": "Wait a few days to see if anything strange happens before bothering the team.", "ar": "ينتظر أيامًا ليرى إن كان سيحدث شيء غريب قبل أن يزعج الفريق."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.options(id,question_id,position,label) values ('519b54d5-05a2-5543-b9a6-60b29ee0d51c','7b0cfcee-b32c-5852-a255-5669ba40fe74',3,'{"en": "Delete the email so no one else opens it and carry on working.", "ar": "يحذف البريد كي لا يفتحه أحد آخر ويواصل عمله."}'::jsonb) on conflict (id) do update set label=excluded.label;
insert into public.answer_keys(question_id,correct_option_id,feedback) values ('7b0cfcee-b32c-5852-a255-5669ba40fe74','1dd9589a-12cd-5e3d-afa2-15f03f746d42','{"en": {"threat": "Incident reporting and response", "lesson": "Quick reporting limits damage: the team can reset access, look for forwarding rules and warn colleagues who received the same email. A hidden incident costs far more than an honest mistake, so report early.", "wrong": ["A silent fix hides the incident. The attacker may already have used the access, and colleagues may have the same email.", "", "Delay gives the attacker time. The speed of response limits the damage.", "Deleting removes evidence and leaves colleagues unwarned."]}, "ar": {"threat": "الإبلاغ عن الحوادث والاستجابة لها", "lesson": "الإبلاغ السريع يحد من الضرر: يستطيع الفريق إعادة ضبط الوصول، والبحث عن قواعد إعادة التوجيه، وتحذير الزملاء الذين وصلهم البريد نفسه. الحادث المخفي أكلف بكثير من خطأ صادق، فبادر بالإبلاغ.", "wrong": ["الإصلاح الصامت يخفي الحادث. قد يكون المهاجم استخدم الوصول فعلًا، وقد يكون لدى زملائه البريد نفسه.", "", "التأخير يمنح المهاجم وقتًا. وسرعة الاستجابة تحدّ من الضرر.", "الحذف يزيل الأدلة ويترك الزملاء بلا تحذير."]}}'::jsonb) on conflict (question_id) do update set correct_option_id=excluded.correct_option_id, feedback=excluded.feedback;
